DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_TEXT_1','Children of the Kingdom[NEWLINE]A fixed prayer cycle with permanent capital development[NEWLINE]Culture or Diplomacy; Science through a protected economy[NEWLINE][NEWLINE]Pray consistently, build permanent Grace through completed cycles, and protect the capital that receives its lasting yields. Temporary blessings are powerful at the right time, but the petition order cannot be freely rearranged.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_TEXT_2','Found Sanctuary, use the first petition when available, and establish ordinary food, production and defense. Plan Houses of Prayer and a stable home front instead of assuming the prayer cycle provides an instant answer to every threat.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_TEXT_3','Check the next petition and cooldown before scheduling construction or a war. Seek applies empire Culture, Ask supports the capital, and Protection has its own defensive window. Completing the cycle is the route to permanent Grace.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_TEXT_4','Use developed cities and accumulated capital yields for the chosen victory. Preserve Keepers and coordinate their support with ordinary units. At the Grace cap, continue using the cycle for its actual remaining rewards rather than expecting infinite permanent stacks.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_TEXT_5','- A completed prayer cycle develops permanent capital Faith and Culture.[NEWLINE]- The sequence includes economic, Happiness and defensive tools.[NEWLINE]- Houses and veteran Keepers fit a stable, protected empire.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_TEXT_6','- Petitions follow a fixed sequence and a speed-scaled cooldown.[NEWLINE]- Permanent Grace has a cap and is concentrated in the current capital.[NEWLINE]- The player must return to the world map and make valid prayer choices.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_TEXT_7','- Observe the defensive blessing and avoid attacking a prepared city at its strongest moment.[NEWLINE]- Apply pressure when the next petition is an economic effect rather than immediate Protection.[NEWLINE]- Contest the capital''s productive base and the diplomatic or cultural plan it supports.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_TEXT_8','- Waiting for a perfect moment indefinitely and delaying every later petition.[NEWLINE]- Expecting to choose Protection directly from any stage.[NEWLINE]- Assuming more completed cycles raise Grace without a cap.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A correctly timed Protection window and prepared defenders can help absorb a limited potion offensive.[NEWLINE][NEWLINE]Viltrum: A stable protected home front can exploit the enemy''s biological crisis rather than meeting its elite force at full strength.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Fast settlement can claim the territory a slower, capital-oriented opening still needs.[NEWLINE][NEWLINE]The Filthy Realm: Concentrated economic disruption pressures the capital while the prayer sequence may be several steps from the desired response.');
