INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_STRATEGY','Pray consistently, build permanent Grace through completed cycles, and protect the capital that receives its lasting yields. Temporary blessings are powerful at the right time, but the petition order cannot be freely rearranged.[NEWLINE][NEWLINE]Found Sanctuary, use the first petition when available, and establish ordinary food, production and defense. Plan Houses of Prayer and a stable home front instead of assuming the prayer cycle provides an instant answer to every threat.[NEWLINE][NEWLINE]Check the next petition and cooldown before scheduling construction or a war. Seek applies empire Culture, Ask supports the capital, and Protection has its own defensive window. Completing the cycle is the route to permanent Grace.[NEWLINE][NEWLINE]Use developed cities and accumulated capital yields for the chosen victory. Preserve Keepers and coordinate their support with ordinary units. At the Grace cap, continue using the cycle for its actual remaining rewards rather than expecting infinite permanent stacks.');
