INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_LEADER_TEXT_2','Found Sanctuary, use the first petition when available, and establish ordinary food, production and defense. Plan Houses of Prayer and a stable home front instead of assuming the prayer cycle provides an instant answer to every threat.[NEWLINE][NEWLINE]Check the next petition and cooldown before scheduling construction or a war. Seek applies empire Culture, Ask supports the capital, and Protection has its own defensive window. Completing the cycle is the route to permanent Grace.[NEWLINE][NEWLINE]Use developed cities and accumulated capital yields for the chosen victory. Preserve Keepers and coordinate their support with ordinary units. At the Grace cap, continue using the cycle for its actual remaining rewards rather than expecting infinite permanent stacks.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECHILDRENOFTHEKINGDOM_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A correctly timed Protection window and prepared defenders can help absorb a limited potion offensive.[NEWLINE][NEWLINE]Viltrum: A stable protected home front can exploit the enemy''s biological crisis rather than meeting its elite force at full strength.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Fast settlement can claim the territory a slower, capital-oriented opening still needs.[NEWLINE][NEWLINE]The Filthy Realm: Concentrated economic disruption pressures the capital while the prayer sequence may be several steps from the desired response.');
